#include <ESP8266WiFi.h>
#include <FirebaseESP8266.h>
#include <DHT.h>
#include <WiFi.h>

// Thông tin mạng và Firebase
#define WIFI_SSID "Tên_Wifi_Của_Bạn"
#define WIFI_PASSWORD "Mật_Khẩu_Wifi"
#define FIREBASE_HOST "URL_Dự_Án_Của_Bạn.firebaseio.com"
#define FIREBASE_AUTH "Mã_Secret_Của_Bạn"

#define DHTPIN 2     // Sử dụng GPIO2
#define DHTTYPE DHT11
DHT dht(DHTPIN, DHTTYPE);

FirebaseData fbdo;

void setup() {
  Serial.begin(115200);
    WiFi.begin(WIFI_SSID, WIFI_PASSWORD);

        while (WiFi.status() != WL_CONNECTED) delay(500);

          Firebase.begin(FIREBASE_HOST, FIREBASE_AUTH);
            dht.begin();
            }

            void loop() {
              float h = dht.readHumidity();
                float t = dht.readTemperature();

                  // Kiểm tra nếu cảm biến đọc lỗi
                    if (isnan(h) || isnan(t)) return;

                      // Đẩy dữ liệu lên Firebase
                        Firebase.setFloat(fbdo, "/NhietDo", t);
                          Firebase.setFloat(fbdo, "/DoAm", h);

                            delay(10000); // Đợi 10 giây mỗi lần cập nhật để tránh quá tải
                            }
